using System;using System.IO;using System.Linq;using System.Text;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class MatchRoofs087 {
 static void Capture(Transform h,string file){var g=new GameObject("Temporary_Roof087_Camera");var rt=new RenderTexture(1400,1000,24);var tx=new Texture2D(1400,1000,TextureFormat.RGB24,false);var old=RenderTexture.active;try{var c=g.AddComponent<Camera>();c.transform.position=h.TransformPoint(new Vector3(-10,9,-12));c.transform.LookAt(h.TransformPoint(new Vector3(0,3,.5f)));c.fieldOfView=48;c.farClipPlane=180;c.targetTexture=rt;c.Render();RenderTexture.active=rt;tx.ReadPixels(new Rect(0,0,1400,1000),0,0);tx.Apply();File.WriteAllBytes("Docs/assets/examples/"+file+".png",tx.EncodeToPNG());}finally{RenderTexture.active=old;UnityEngine.Object.DestroyImmediate(g);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tx);}}
 public static string Main(){var s=UnityEngine.SceneManagement.SceneManager.GetActiveScene();if(s.path!="Assets/Scenes/CastleServicesWorkshop.unity"||s.isDirty||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Saved castle Edit Mode required");if(!File.Exists("Library/WorkshopBackups/DB-ON-087/OwnerSaved.unity"))throw new Exception("Checkpoint missing");var hs=GameObject.Find("Castle_Services_Prototype").transform.Find("03_Service_Houses");var trader=hs.Find("03_LootTrader");var armory=hs.Find("04_Professions");
 var tradeStyle=trader.Find("04_Roof").GetComponentsInChildren<MeshRenderer>(true).GroupBy(r=>r.GetComponent<MeshFilter>().sharedMesh).ToDictionary(g=>g.Key,g=>g.First().sharedMaterials.ToArray());var armoryStyle=armory.Find("04_Roof").GetComponentsInChildren<MeshRenderer>(true).GroupBy(r=>r.GetComponent<MeshFilter>().sharedMesh).ToDictionary(g=>g.Key,g=>g.First().sharedMaterials.ToArray());var report=new StringBuilder();
 foreach(string name in new[]{"01_Supplies","02_Armory","03_LootTrader"}){var h=hs.Find(name);var style=name=="03_LootTrader"?armoryStyle:tradeStyle;int changed=0;foreach(var r in h.Find("04_Roof").GetComponentsInChildren<MeshRenderer>(true)){var mesh=r.GetComponent<MeshFilter>().sharedMesh;if(!style.ContainsKey(mesh))throw new Exception("Roof geometry has no source counterpart: "+name+"/"+r.name);var b=r.bounds;var materials=style[mesh];if(!r.sharedMaterials.SequenceEqual(materials)){Undo.RecordObject(r,"Match roof style");r.sharedMaterials=materials;PrefabUtility.RecordPrefabInstancePropertyModifications(r);changed++;}if(r.bounds!=b||!r.sharedMaterials.SequenceEqual(materials))throw new Exception("Bounds/material mismatch");}report.AppendLine(name+": exact "+(name=="03_LootTrader"?"original armory":"original trader")+" material references on all matching roof meshes; changed renderers="+changed+"; geometry, bounds, transforms, colliders unchanged.");Capture(h,"Roof087_"+name);}
 EditorSceneManager.MarkSceneDirty(s);AssetDatabase.SaveAssets();if(!EditorSceneManager.SaveScene(s))throw new Exception("Save failed");File.WriteAllText("Docs/assets/examples/ROOFS087_VALIDATION.txt",report.ToString());return report.ToString();}
}
